// auto-deploy enabled
const DATA_VERSION=20260705;
const ICON192_B64='';
const ICON512_B64='';
const MANIFEST_B64='';
const SW_B64='';
const HTML_B64 = '';
function hashStr(s){var h=5381;for(var i=0;i<s.length;i++){h=((h<<5)+h+s.charCodeAt(i))|0;}return (h>>>0).toString(36);}
const BUILD_HASH = hashStr(HTML_B64);
function b64decode(str){const b=atob(str);const bytes=new Uint8Array(b.length);for(let i=0;i<b.length;i++){bytes[i]=b.charCodeAt(i);}return new TextDecoder().decode(bytes);}
function b64bytes(str){const b=atob(str);const u=new Uint8Array(b.length);for(let i=0;i<b.length;i++){u[i]=b.charCodeAt(i);}return u;}
const NC={'Cache-Control':'no-store, no-cache, must-revalidate, max-age=0','Pragma':'no-cache','Expires':'0'};
export default {async fetch(request){
  const p=new URL(request.url).pathname;
  if(p==='/manifest.json'){return new Response(b64decode(MANIFEST_B64),{headers:Object.assign({'Content-Type':'application/manifest+json; charset=UTF-8'},NC)});}
  if(p==='/sw.js'){return new Response(b64decode(SW_B64),{headers:Object.assign({'Content-Type':'application/javascript; charset=UTF-8'},NC)});}
  if(p==='/icon-192.png'){return new Response(b64bytes(ICON192_B64),{headers:{'Content-Type':'image/png','Cache-Control':'public, max-age=604800'}});}
  if(p==='/icon-512.png'){return new Response(b64bytes(ICON512_B64),{headers:{'Content-Type':'image/png','Cache-Control':'public, max-age=604800'}});}
  return new Response(b64decode(HTML_B64),{headers:Object.assign({'Content-Type':'text/html; charset=UTF-8','X-Data-Version':String(DATA_VERSION),'X-App-Version':BUILD_HASH},NC)});
}};
